import os, hashlib, math
from pathlib import Path

def entropy(data):
    if not data: return 0
    counts = [0] * 256
    for b in data:
        counts[b] += 1
    e = 0
    for c in counts:
        if c:
            p = c / len(data)
            e -= p * math.log2(p)
    return e

def sha256(path):
    h = hashlib.sha256()
    with open(path, 'rb') as f:
        for chunk in iter(lambda: f.read(65536), b''):
            h.update(chunk)
    return h.hexdigest()

def triage(path):
    with open(path, 'rb') as f:
        data = f.read()
    return {
        'path': path,
        'size': len(data),
        'sha256': sha256(path),
        'entropy': round(entropy(data[:65536]), 2),
        'is_pe': data[:2] == b'MZ',
        'is_elf': data[:4] == b'\x7fELF',
    }

