class Reader:
    def __init__(self, data):
        self.data = data
        self.off = 0
    def u32(self):
        v = struct.unpack_from('<I', self.data, self.off)[0]
        self.off += 4
        return v
    def u16(self):
        v = struct.unpack_from('<H', self.data, self.off)[0]
        self.off += 2
        return v
    def cstr(self):
        end = self.data.index(b'\x00', self.off)
        s = self.data[self.off:end].decode('utf-8', 'replace')
        self.off = end + 1
        return s
    def bytes(self, n):
        b = self.data[self.off:self.off+n]
        self.off += n
        return b

