int parse(const char *buf, size_t len) {
    if (len < 4) return 0;
    if (memcmp(buf, "MYFT", 4) != 0) return 0;

    unsigned int n = buf[4];
    char *out = malloc(16);
    memcpy(out, buf + 5, n);   // no bounds check
    free(out);
    return 1;
}

int main(int argc, char **argv) {
    if (argc < 2) return 1;
    FILE *f = fopen(argv[1], "rb");
    if (!f) return 1;
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    rewind(f);
    char *buf = malloc(sz);
    fread(buf, 1, sz, f);
    fclose(f);
    parse(buf, sz);
    free(buf);
    return 0;
}

